import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"Release a GOAT build","description":"","frontmatter":{},"headers":[],"relativePath":"Releasing.md","filePath":"wiki/Releasing.md","lastUpdated":1789092097000}`),u={name:`Releasing.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[11]||=c(`h1`,{id:`release-a-goat-build`,tabindex:`-1`},[i(`Release a GOAT build `),c(`a`,{class:`header-anchor`,href:`#release-a-goat-build`,"aria-label":`Permalink to “Release a GOAT build”`},`​`)],-1),c(`p`,null,[l[3]||=i(`This guide is for maintainers. The current maintenance release’s canonical version is `,-1),l[4]||=c(`code`,null,`0.1.1`,-1),l[5]||=i(`, public label `,-1),c(`strong`,null,[l[1]||=i(`0.1.1 (`,-1),r(m,{term:`kid`},{default:n(()=>[...l[0]||=[i(`Kid`,-1)]]),_:1}),l[2]||=i(`)`,-1)]),l[6]||=i(` and release tag `,-1),l[7]||=c(`code`,null,`v0.1.1`,-1),l[8]||=i(`. The published 0.1.0 release remains unchanged. Identity comes from `,-1),l[9]||=c(`code`,null,`apps/goat-macos/release.json`,-1),l[10]||=i(`.`,-1)]),l[12]||=a(`<ol><li>Review <a href="/RELEASE-CHECKLIST">Release readiness</a>. Complete content, distribution, live-service, clean-machine and performance checks appropriate to the release.</li><li>Follow <a href="/VERSIONING">Versioning</a> to generate metadata, build a separate candidate and verify source/bundle/artifact agreement. Do not restart an app doing active work.</li><li>Record the candidate’s exact source revision and evidence. A later commit or squash requires a newly qualified artifact; old manifests cannot be relabelled.</li><li>After approval, tag the final accepted commit. When enabled, the release workflow checks the tag and builds a <strong>draft</strong> release. For a locally signed release, upload the exact qualified artifacts to a draft targeting that commit; keep automated signing disabled.</li><li>Review signing/notarization, the mounted DMG, checksums, notices, instructions and release notes before publishing the draft.</li></ol><p>Repository visibility, website deployment and release publication are separate operations. The Pages workflow is manual-only and requires both its publication variable and explicit input. See <a href="https://github.com/goatsoft/GOAT/blob/main/web/README.md" target="_blank" rel="noreferrer">Website maintenance</a>.</p><p>Use private Actions secrets for Developer ID and notarization credentials. An ad hoc candidate does not establish clean-machine Gatekeeper acceptance. CI uses a macOS 26 runner for app verification; successful CI alone does not close interactive acceptance.</p><h2 id="public-preview-before-the-first-release" tabindex="-1">Public preview before the first release <a class="header-anchor" href="#public-preview-before-the-first-release" aria-label="Permalink to “Public preview before the first release”">​</a></h2><p>The source repository and both websites can open before an app release is tagged. Keep <code>web/publication.json</code> at <code>releaseTag: null</code>; the website then links to source-build instructions. Use the <a href="/PUBLIC-PREVIEW">feedback guide</a> to explain the scope and collect feedback.</p><p>Before the first public push, archive the development history privately, review the exact distributable tree and prepare one initial commit. Verify that commit from a fresh clone, including source builds, documentation, dependency notices and example packages. Do not publish archive branches or old tags. Once contributors can clone the public repository, preserve normal history instead of squashing it again.</p><p>Push the initial <code>main</code> to the private repository with publication disabled and let CI run. Review repository metadata, community links and any existing Actions logs before changing visibility. Configure branch protections, private vulnerability reporting and release-tag ownership. Required release-signing approval must be available and verified before adding signing secrets.</p><p>After source and content review, make the repositories public and manually publish both sites using <a href="https://github.com/goatsoft/GOAT/blob/main/web/README.md" target="_blank" rel="noreferrer">Website maintenance</a>. Check HTTPS, navigation, search, legal pages and source-build links on the actual domains. No version tag or draft binary release is needed for this stage.</p><p>Release qualification continues during the preview. Signing, notarization and clean-Mac acceptance are required before official downloads; they are not claims made by publishing source. When the final commit is accepted, follow the tagged release procedure above. Publish the approved download before enabling its website link, then deploy the launch copy and announce availability.</p><h2 id="signing-setup" tabindex="-1">Signing setup <a class="header-anchor" href="#signing-setup" aria-label="Permalink to “Signing setup”">​</a></h2><p>Contributor builds default to ad-hoc signing. For a stable local identity, create an ignored <code>apps/goat-macos/signing.local.mk</code> file with your certificate&#39;s exact name and team:</p><div class="language-make"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">make</span><pre class="shiki shiki-themes github-light github-dark-dimmed" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">CODE_SIGN_IDENTITY = Apple Development: Your Name (CERTIFICATE_ID)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">RELEASE_SIGNING_IDENTITY = Developer ID Application: Your Name (YOURTEAMID)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">DEVELOPMENT_TEAM = YOURTEAMID</span></span></code></pre></div><p>Use <code>security find-identity -v -p codesigning</code> to find installed identities. A Developer ID Application identity can also sign local acceptance builds. <code>make build</code>, <code>make test-app</code> and <code>make release</code> pass these settings to Xcode. A certificate fingerprint can select an exact identity when names are duplicated. Command-line make assignments override the local file. <code>RELEASE_SIGNING_IDENTITY</code> defaults to <code>CODE_SIGN_IDENTITY</code> when not set. Certificates and their private keys stay in Keychain; the local file contains only the signing selection. Keep test harnesses separately signed and isolated from the normal app.</p><p>Official downloads use Developer ID Application signing with hardened runtime. The release workflow verifies the app and CLI&#39;s publisher and team, requires notarization to return Accepted, staples and validates the ticket, then records final checksums. It creates a draft for manual publication. See <a href="https://developer.apple.com/developer-id/" target="_blank" rel="noreferrer">Apple&#39;s Developer ID guidance</a>.</p><h2 id="local-notarization" tabindex="-1">Local notarization <a class="header-anchor" href="#local-notarization" aria-label="Permalink to “Local notarization”">​</a></h2><p>Local notarization can use a Keychain profile without exporting signing credentials to GitHub. Run <code>xcrun notarytool store-credentials &quot;GOAT-notary&quot;</code> in your terminal and follow its prompts for your Apple Account, team and app-specific password. For a locally packaged DMG, first sign the container with <code>codesign --timestamp --sign &quot;Developer ID Application: Your Name (YOURTEAMID)&quot; /path/to/GOAT-0.1.1.dmg</code>. This is separate from signing the app and CLI inside it. Then run <code>NOTARY_KEYCHAIN_PROFILE=GOAT-notary DMG=/path/to/GOAT-0.1.1.dmg ./scripts/notarize.sh</code> from <code>apps/goat-macos/</code>. The script still requires Apple&#39;s Accepted result and validates the stapled ticket. Regenerate the artifact manifest and checksums after stapling. This does not enable the GitHub release workflow or replace clean-Mac acceptance.</p><h2 id="github-approval-gate" tabindex="-1">GitHub approval gate <a class="header-anchor" href="#github-approval-gate" aria-label="Permalink to “GitHub approval gate”">​</a></h2><p>Configure these controls before enabling the workflow:</p><ol><li>Create the <code>release-signing</code> environment in <code>goatsoft/GOAT</code>. Require approval from the release owner. Allow that owner to approve their own runs, since the same person creates release tags. Disable administrator bypass and restrict deployment to <code>v*</code> tags.</li><li>Restrict creation, updates and deletion of release tags to the owner through a repository tag ruleset. Protect the release workflow and scripts through the repository&#39;s review rules.</li><li>Store the signing and notarization credentials <strong>only in that environment</strong>, not as repository or organisation secrets: <code>MACOS_CERTIFICATE</code> (base64 PKCS#12 certificate/private-key export), <code>MACOS_CERTIFICATE_PASSWORD</code>, <code>MACOS_SIGNING_IDENTITY</code> (exact Developer ID Application name), <code>APPLE_TEAM_ID</code>, <code>NOTARY_APPLE_ID</code>, and <code>NOTARY_PASSWORD</code> (an app-specific password).</li><li>Set repository variable <code>GOAT_RELEASE_OWNER</code> to the owner&#39;s GitHub login. Set <code>GOAT_RELEASE_SIGNING_ENABLED</code> to <code>true</code> only after testing the environment&#39;s approval requirement. Missing or different values leave the workflow disabled.</li></ol><p>Required reviewers are available for public repositories on GitHub Free, Pro and Team. Private repositories need an eligible Enterprise plan for this protection. While the repository is private without that feature, leave CI signing disabled and keep the signing key local. Making the repository public remains a separate publication decision. See <a href="https://docs.github.com/en/actions/how-tos/managing-workflow-runs-and-deployments/managing-deployments/reviewing-deployments" target="_blank" rel="noreferrer">GitHub&#39;s environment requirements</a>.</p><p>The workflow runs only in the official repository for tags pushed by the configured owner, including checks on the actor requesting a rerun. Verification runs in a separate job without signing credentials. The signing job uses <code>release-signing</code>, so its environment secrets become available only after the configured approval. Fork and pull-request builds do not receive official signing credentials. A YAML environment name alone does not configure required reviewers; complete the repository settings above first.</p>`,21)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};